-- V62 Java was removed intentionally; V62/V63 SQL remain unchanged by this forward migration.
-- Original definitions are retained for review/restore, including user edits.
create table if not exists automation_workflow_backup (
    trigger_id bigint not null, migration_version integer not null, definition jsonb not null,
    saved_at timestamptz not null default now(), primary key(trigger_id, migration_version)
);
create table if not exists automation_operation_receipt (
    execution_key text primary key, operation varchar(128) not null, result jsonb,
    created_at timestamptz not null default now()
);
create table if not exists automation_graph_memory (
    memory_key text primary key, created_at timestamptz not null default now()
);
create table if not exists automation_graph_trace (
    id bigserial primary key, execution_id varchar(128) not null, trigger_id bigint,
    created_at timestamptz not null default now(), step jsonb not null
);
create index if not exists idx_automation_graph_trace_trigger on automation_graph_trace(trigger_id, id desc);

insert into automation_workflow_backup(trigger_id, migration_version, definition) select id, 64, to_jsonb(t) from automation_trigger t where name = 'Нужен ответ (Jev)' on conflict do nothing;

update automation_trigger set workflow_version = 3, workflow_definition = (
    select jsonb_set(graph, '{nodes,1,config,parameters}', (
        select jsonb_agg(case
          when p->>'migrationSetting' = 'replyRequired' then jsonb_set(p, '{value}', coalesce((select to_jsonb(jev_reply_required_threshold) from app_settings order by id limit 1),p->'value'))
          when p->>'migrationSetting' = 'replyNotRequired' then jsonb_set(p, '{value}', coalesce((select to_jsonb(jev_reply_not_required_threshold) from app_settings order by id limit 1),p->'value'))
          when p->>'migrationSetting' = 'priorityExcluded' then jsonb_set(p, '{value}', coalesce((select to_jsonb(string_to_array(jev_priority_excluded, chr(10))) from app_settings order by id limit 1),p->'value'))
          when p ? 'migrationSetting' then jsonb_set(p, '{value}', coalesce((select cast(jev_thresholds as jsonb)->(p->>'migrationSetting') from app_settings order by id limit 1),p->'value'))
          else p end order by position)
        from jsonb_array_elements(graph#>'{nodes,1,config,parameters}') with ordinality as params(p,position)
    ))::text from (values ($graph$
{"version":3,"entryNodeId":"reply-1","nodes":[{"id":"reply-1","type":"EVENT","label":"Когда запускать","x":80,"y":100,"config":{"section":"1. Настройки","triggerType":"MESSAGE_INCOMING"}},{"id":"reply-2","type":"PARAMETERS","label":"Настройки сценария","x":500,"y":100,"config":{"section":"1. Настройки","resultVariable":"settings","parameters":[{"name":"required","label":"Ответ нужен при вероятности от","value":0.6,"help":"","type":"number","migrationSetting":"replyRequired","min":0,"max":1},{"name":"notRequired","label":"Ответ не нужен при вероятности до","value":0.25,"help":"","type":"number","migrationSetting":"replyNotRequired","min":0,"max":1}],"description":"Начните с этого блока: здесь меняются пороги, интервалы и ограничения. Остальные шаги используют эти значения."}},{"id":"reply-5","type":"OPERATION","label":"Определить, ждёт ли клиент ответа","x":80,"y":570,"config":{"section":"2. Оценка сообщения","operation":"ai.decide","arguments":{"state":"=message.text","question":"Нужен ли ответ оператора поддержки на последнее сообщение клиента? Вопрос, проблема и ожидание действий — ДА. Благодарность, подтверждение, прощание и эмодзи без вопроса — НЕТ.","kind":"noul","options":{},"yes":"Да","no":"Нет"},"resultVariable":"decision"}},{"id":"reply-6","type":"CONDITION","label":"Jev вернул оценку?","x":500,"y":570,"config":{"section":"2. Оценка сообщения","expression":"var.decision.available","manualExpression":true,"groups":[],"rule":{"left":"=var.decision.available","operator":"true"}}},{"id":"reply-7","type":"CONDITION","label":"Вероятность выше порога «нужен ответ»?","x":920,"y":570,"config":{"section":"2. Оценка сообщения","expression":"var.decision.probability >= var.settings.required","manualExpression":true,"groups":[],"rule":{"left":"=var.decision.probability","operator":">=","right":"=var.settings.required"}}},{"id":"reply-8","type":"OPERATION","label":"Пометить: нужен ответ","x":80,"y":1290,"config":{"section":"3. Метка ответа","operation":"client.replyFlag","arguments":{"clientId":"=client.id","messageId":"=message.id","required":true},"resultVariable":""}},{"id":"reply-9","type":"CONDITION","label":"Вероятность ниже порога «ответ не нужен»?","x":80,"y":1540,"config":{"section":"3. Метка ответа","expression":"var.decision.probability <= var.settings.notRequired","manualExpression":true,"groups":[],"rule":{"left":"=var.decision.probability","operator":"<=","right":"=var.settings.notRequired"}}},{"id":"reply-10","type":"OPERATION","label":"Пометить: ответ не нужен","x":500,"y":1290,"config":{"section":"3. Метка ответа","operation":"client.replyFlag","arguments":{"clientId":"=client.id","messageId":"=message.id","required":false},"resultVariable":""}},{"id":"reply-11","type":"END","label":"Ошибка — посмотреть журнал","x":500,"y":820,"config":{"section":"2. Оценка сообщения","result":"Шаг не выполнен. Причина указана в журнале."}},{"id":"reply-12","type":"END","label":"На этом закончить","x":920,"y":820,"config":{"section":"2. Оценка сообщения","result":"Дополнительные действия не требуются"}},{"id":"reply-13","type":"END","label":"На этом закончить","x":920,"y":1290,"config":{"section":"3. Метка ответа","result":"Дополнительные действия не требуются"}},{"id":"reply-14","type":"END","label":"Ошибка — посмотреть журнал","x":920,"y":1540,"config":{"section":"3. Метка ответа","result":"Шаг не выполнен. Причина указана в журнале."}}],"edges":[{"id":"reply-edge-reply-1-next","source":"reply-1","target":"reply-2","sourceHandle":"next"},{"id":"reply-edge-reply-2-next","source":"reply-2","target":"reply-5","sourceHandle":"next"},{"id":"reply-edge-reply-5-success","source":"reply-5","target":"reply-6","sourceHandle":"success"},{"id":"reply-edge-reply-6-true","source":"reply-6","target":"reply-7","sourceHandle":"true"},{"id":"reply-edge-reply-7-true","source":"reply-7","target":"reply-8","sourceHandle":"true"},{"id":"reply-edge-reply-7-false","source":"reply-7","target":"reply-9","sourceHandle":"false"},{"id":"reply-edge-reply-9-true","source":"reply-9","target":"reply-10","sourceHandle":"true"},{"id":"reply-edge-reply-5-error","source":"reply-5","target":"reply-11","sourceHandle":"error"},{"id":"reply-edge-reply-6-false","source":"reply-6","target":"reply-12","sourceHandle":"false"},{"id":"reply-edge-reply-8-success","source":"reply-8","target":"reply-13","sourceHandle":"success"},{"id":"reply-edge-reply-8-error","source":"reply-8","target":"reply-14","sourceHandle":"error"},{"id":"reply-edge-reply-9-false","source":"reply-9","target":"reply-13","sourceHandle":"false"},{"id":"reply-edge-reply-10-success","source":"reply-10","target":"reply-13","sourceHandle":"success"},{"id":"reply-edge-reply-10-error","source":"reply-10","target":"reply-14","sourceHandle":"error"}]}
$graph$::jsonb)) as source(graph)
), description = 'Прозрачный граф: настройки, данные, оценка, условия и отдельные действия. Изменяйте параметры и шаги в редакторе.' where name = 'Нужен ответ (Jev)';

