insert into automation_workflow_backup(trigger_id, migration_version, definition) select id, 64, to_jsonb(t) from automation_trigger t where name = 'Эскалация на следующую линию (Jev)' on conflict do nothing;

update automation_trigger set workflow_version = 3, workflow_definition = (
    select jsonb_set(graph, '{nodes,1,config,parameters}', (
        select jsonb_agg(case
          when p->>'migrationSetting' = 'replyRequired' then jsonb_set(p, '{value}', coalesce((select to_jsonb(jev_reply_required_threshold) from app_settings order by id limit 1),p->'value'))
          when p->>'migrationSetting' = 'replyNotRequired' then jsonb_set(p, '{value}', coalesce((select to_jsonb(jev_reply_not_required_threshold) from app_settings order by id limit 1),p->'value'))
          when p->>'migrationSetting' = 'priorityExcluded' then jsonb_set(p, '{value}', coalesce((select to_jsonb(string_to_array(jev_priority_excluded, chr(10))) from app_settings order by id limit 1),p->'value'))
          when p ? 'migrationSetting' then jsonb_set(p, '{value}', coalesce((select cast(jev_thresholds as jsonb)->(p->>'migrationSetting') from app_settings order by id limit 1),p->'value'))
          else p end order by position)
        from jsonb_array_elements(graph#>'{nodes,1,config,parameters}') with ordinality as params(p,position)
    ))::text from (values ($graph$
{"version":3,"entryNodeId":"escalation-1","nodes":[{"id":"escalation-1","type":"EVENT","label":"Когда запускать","x":80,"y":100,"config":{"section":"1. Настройки","triggerType":"MESSAGE_INCOMING"}},{"id":"escalation-2","type":"PARAMETERS","label":"Настройки сценария","x":500,"y":100,"config":{"section":"1. Настройки","resultVariable":"settings","parameters":[{"name":"threshold","label":"Минимальная уверенность Jev","value":0.6,"help":"Ниже порога данные не меняются.","type":"number","migrationSetting":"escalateIfNeeded","min":0,"max":1},{"name":"minMinutes","label":"Минимум минут на текущей линии","value":10,"help":"Меняйте ожидание здесь.","type":"number","min":0,"max":10080},{"name":"messages","label":"Сообщений контекста","value":8,"help":"","type":"number","min":1,"max":100}],"description":"Начните с этого блока: здесь меняются пороги, интервалы и ограничения. Остальные шаги используют эти значения."}},{"id":"escalation-5","type":"OPERATION","label":"Заявки клиента","x":80,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"data.tasks","arguments":{"clientId":"=client.id"},"resultVariable":"tasks"}},{"id":"escalation-6","type":"OPERATION","label":"Отобрать: openTasks","x":500,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"list.select","arguments":{"items":"=var.tasks","where":"!var.item.completed","sortBy":"createdAt","descending":true,"limit":1},"resultVariable":"openTasks"}},{"id":"escalation-7","type":"CONDITION","label":"Есть открытая заявка?","x":920,"y":570,"config":{"section":"2. Заявка и возможные линии","expression":"var.openTasks.size() > 0","manualExpression":true,"groups":[],"rule":{"left":"=var.openTasks.size()","operator":">","right":0}}},{"id":"escalation-8","type":"OPERATION","label":"Последняя открытая заявка","x":1340,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"value.set","arguments":{"value":"=var.openTasks.first()"},"resultVariable":"targetTask"}},{"id":"escalation-9","type":"CONDITION","label":"Текущая линия определена?","x":1760,"y":570,"config":{"section":"2. Заявка и возможные линии","expression":"var.targetTask.lineId.notNull()","manualExpression":true,"groups":[],"rule":{"left":"=var.targetTask.lineId","operator":"notNull"}}},{"id":"escalation-10","type":"CONDITION","label":"Заявка достаточно долго на линии?","x":2180,"y":570,"config":{"section":"2. Заявка и возможные линии","expression":"var.targetTask.enteredLineAt.isNull() || var.targetTask.enteredLineAt.minutesSince() >= var.settings.minMinutes","manualExpression":true,"groups":[],"rule":{"any":[{"left":"=var.targetTask.enteredLineAt","operator":"null"},{"left":"=var.targetTask.enteredLineAt.minutesSince()","operator":">=","right":"=var.settings.minMinutes"}]}}},{"id":"escalation-11","type":"OPERATION","label":"Все линии поддержки","x":2600,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"data.lines","arguments":{},"resultVariable":"allLines"}},{"id":"escalation-12","type":"OPERATION","label":"Отобрать: currentLines","x":3020,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"list.select","arguments":{"items":"=var.allLines","where":"var.item.id = var.targetTask.lineId","sortBy":"id","descending":false,"limit":1},"resultVariable":"currentLines"}},{"id":"escalation-13","type":"OPERATION","label":"Отобрать: higherLines","x":3440,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"list.select","arguments":{"items":"=var.allLines","where":"var.item.active && var.item.level > var.targetTask.lineLevel","sortBy":"level","descending":false,"limit":100},"resultVariable":"higherLines"}},{"id":"escalation-14","type":"CONDITION","label":"Есть следующая линия?","x":3860,"y":570,"config":{"section":"2. Заявка и возможные линии","expression":"var.higherLines.size() > 0","manualExpression":true,"groups":[],"rule":{"left":"=var.higherLines.size()","operator":">","right":0}}},{"id":"escalation-15","type":"OPERATION","label":"Отобрать: nextLines","x":4280,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"list.select","arguments":{"items":"=var.higherLines","where":"var.item.level = var.higherLines.first().level","sortBy":"id","descending":false,"limit":100},"resultVariable":"nextLines"}},{"id":"escalation-16","type":"OPERATION","label":"Контекст переписки","x":4700,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"data.messages","arguments":{"clientId":"=client.id"},"resultVariable":"messages"}},{"id":"escalation-17","type":"OPERATION","label":"Отобрать: conversation","x":5120,"y":570,"config":{"section":"2. Заявка и возможные линии","operation":"list.select","arguments":{"items":"=var.messages","where":"!var.item.comment","sortBy":"date","descending":true,"limit":"=var.settings.messages"},"resultVariable":"conversation"}},{"id":"escalation-18","type":"OPERATION","label":"Нужна ли более высокая линия?","x":80,"y":1290,"config":{"section":"3. Решение об эскалации","operation":"ai.decide","arguments":{"state":{"task":"=var.targetTask","currentLine":"=var.currentLines.first()","conversation":"=var.conversation"},"question":"Нужно ли передать заявку на следующую линию? ДА: нужны более глубокая экспертиза, доступы, права; решения текущей линии не помогли. НЕТ: текущая линия может продолжать работу.","kind":"noul","options":{},"yes":"Да","no":"Нет"},"resultVariable":"need"}},{"id":"escalation-19","type":"CONDITION","label":"Jev уверенно рекомендует перевод?","x":500,"y":1290,"config":{"section":"3. Решение об эскалации","expression":"var.need.available && var.need.probability >= var.settings.threshold","manualExpression":true,"groups":[],"rule":{"all":[{"left":"=var.need.available","operator":"true"},{"left":"=var.need.probability","operator":">=","right":"=var.settings.threshold"}]}}},{"id":"escalation-20","type":"CONDITION","label":"На следующем уровне одна линия?","x":920,"y":1290,"config":{"section":"3. Решение об эскалации","expression":"var.nextLines.si