insert into automation_workflow_backup(trigger_id, migration_version, definition) select id, 64, to_jsonb(t) from automation_trigger t where name = 'Проверка восстановления после инцидента (Jev)' on conflict do nothing;

update automation_trigger set workflow_version = 3, workflow_definition = (
    select jsonb_set(graph, '{nodes,1,config,parameters}', (
        select jsonb_agg(case
