ении?","x":80,"y":1290,"config":{"section":"3. Оценка сообщения","operation":"ai.decide","arguments":{"state":{"message":"=message.text","incident":"=var.link.incident"},"question":"Сообщение о проблеме этого инцидента: восстановление подтверждено, проблема сохраняется или сообщение не относится к инциденту?","kind":"choice","options":{"confirmed":"Клиент подтверждает, что всё снова работает","still_broken":"Проблема сохраняется или повторилась","unrelated":"Сообщение не о проблеме этого инцидента"},"yes":"Да","no":"Нет"},"resultVariable":"decision"}},{"id":"recovery-10","type":"CONDITION","label":"Оценка достаточно уверенная?","x":500,"y":1290,"config":{"section":"3. Оценка сообщения","expression":"var.decision.available && var.decision.probability >= var.settings.threshold","manualExpression":true,"groups":[],"rule":{"all":[{"left":"=var.decision.available","operator":"true"},{"left":"=var.decision.probability","operator":">=","right":"=var.settings.threshold"}]}}},{"id":"recovery-11","type":"CONDITION","label":"Восстановление подтверждено?","x":920,"y":1290,"config":{"section":"3. Оценка сообщения","expression":"var.decision.choice = 'confirmed'","manualExpression":true,"groups":[],"rule":{"left":"=var.decision.choice","operator":"=","right":"confirmed"}}},{"id":"recovery-12","type":"OPERATION","label":"Отметить подтверждение клиента","x":80,"y":2010,"config":{"section":"4. Явные действия по результату","operation":"incident.confirm","arguments":{"incidentId":"=var.link.incident.id","taskId":"=var.link.taskId","confirmed":true,"reason":"Jev: клиент #{{ client.id }}, сообщение #{{ message.id }}"},"resultVariable":""}},{"id":"recovery-13","type":"CONDITION","label":"Клиент сообщает о сохраняющейся проблеме?","x":80,"y":2260,"config":{"section":"4. Явные действия по результату","expression":"var.decision.choice = 'still_broken'","manualExpression":true,"groups":[],"rule":{"left":"=var.decision.choice","operator":"=","right":"still_broken"}}},{"id":"recovery-14","typ