$graph$::jsonb)) as source(graph)
), description = 'Прозрачный граф: настройки, данные, оценка, условия и отдельные действия. Изменяйте параметры и шаги в редакторе.' where name = 'Обновления проблем Zabbix в инциденте';

insert into automation_workflow_backup(trigger_id, migration_version, definition) select id, 64, to_jsonb(t) from automation_trigger t where name = 'Детектор массовых инцидентов (Jev)' on conflict do nothing;

update automation_trigger set workflow_version = 3, workflow_definition = (
    select jsonb_set(graph, '{nodes,1,config,parameters}', (
        select jsonb_agg(case
          when p->>'migrationSetting' = 'replyRequired' then jsonb_set(p, '{value}', coalesce((select to_jsonb(jev_reply_required_threshold) from app_settings order by id limit 1),p->'value'))
          when p->>'migrationSetting' = 'replyNotRequired' then jsonb_set(p, '{value}', coalesce((select to_jsonb(jev_reply_not_required_threshold) from app_settings order by id limit 1),p->'value'))
          when p->>'migrationSetting' = 'priorityExcluded' then jsonb_set(p, '{value}', coalesce((select to_jsonb(string_to_array(jev_priority_excluded, chr(10))) from app_settings order by id limit 1),p->'value'))
          when p ? 'migrationSetting' then jsonb_set(p, '{value}', coalesce((select cast(jev_thresholds as jsonb)->(p->>'migrationSetting') from app_settings order by id limit 1),p->'value'))
          else p end order by position)
        from jsonb_array_elements(graph#>'{nodes,1,config,parameters}') with ordinality as params(p,position)
    ))::text from (values ($graph$
{"version":3,"entryNodeId":"outage-1","nodes":[{"id":"outage-1","type":"EVENT","label":"Когда запускать","x":80,"y":100,"config":{"section":"1. Настройки","triggerType":"MESSAGE_INCOMING"}},{"id":"outage-2","type":"PARAMETERS","label":"Настройки сценария","x":500,"y":100,"config":{"section":"1. Настройки","resultVariable":"settings","parameters":[{"name":"analysis","label":"Уверенность выбора сервиса и причины","value":0.6,"help":"","type":"number","migrationSetting":"detectIncident","min":0,"max":1},{"name":"window","label":"Окно подсчёта, минут","value":15,"help":"","type":"number","min":0,"max":10080},{"name":"clients","label":"Минимум разных клиентов","value":3,"help":"","type":"number","min":0,"max":10080},{"name":"alertClients","label":"Минимум клиентов при тревоге мониторинга","value":2,"help":"","type":"number","min":0,"max":10080},{"name":"outage","label":"Вероятность «это сбой»","value":0.7,"help":"","type":"number","min":0,"max":1},{"name":"cooldown","label":"Пауза после срабатывания, минут","value":60,"help":"","type":"number","min":0,"max":10080},{"name":"sameProblem","label":"Вероятность общей проблемы","value":0.6,"help":"","type":"number","min":0,"max":1},{"name":"p1Clients","label":"Клиентов для P1","value":10,"help":"","type":"number","min":0,"max":10080},{"name":"createDraft","label":"При срабатывании создавать черновик инцидента","value":false,"help":"Если выключено — только уведомление.","type":"boolean"},{"name":"p1Interval","label":"Интервал обновлений P1, минут","value":15,"help":"","type":"number","min":1,"max":10080},{"name":"p2Interval","label":"Интервал обновлений P2, минут","value":30,"help":"","type":"number","min":1,"max":10080},{"name":"p3Interval","label":"Интервал обновлений P3, минут","value":60,"help":"","type":"number","min":1,"max":10080},{"name":"p4Interval","label":"Интервал обновлений P4, минут","value":120,"help":"","type":"number","min":1,"max":10080}],"description":"Начните с этого блока: здесь меняются пороги, интервалы и ограничения. Остальные шаги используют эти значения."}},{"id":"inc-analyze","type":"OPERATION","label":"Jev: разметка сообщения","x":80,"y":570,"config":{"section":"2. Разметка и подсчёт обращений","arguments":{"analysisThreshold":"=var.settings.analysis"},"resultVariable":"outage","operation":"signal.analyze"}},{"id":"inc-c-answer","type":"CONDITION","label":"Jev ответил?","x":500,"y":570,"config":{"expression":"var.outage.notNull()","groups":[],"manualExpression":true,"section":"2. Разметка и подсчёт обращений","rule":{"left":"=var.outage","operator":"notNull"}}},{"id":"inc-c-matched","type":"CONDITION","label":"Относится к открытому инциденту?","x":920,"y":570,"config":{"expression":"var.outage.matchedIncidentId.notNull()","groups":[],"manualExpression":true,"section":"2. Разметка и подсчёт обращений","rule":{"left":"=var.outage.matchedIncidentId","operator":"notNull"}}},{"id":"inc-attach-matched","type":"CONDITION","label":"Отметить: тот же инцидент","x":1340,"y":570,"config":{"section":"2. Разметка и подсчёт обращений","arguments":{},"resultVariable":"","expression":"var.settings.createDraft","manualExpression":true,"rule":{"left":"=var.settings.createDraft","operator":"true"}}},{"id":"inc-c-outage","type":"CONDITION","label":"Это сбой с понятным сервисом?","x":1340,"y":820,"config":{"expression":"var.outage.serviceId.notNull() && var.outage.probability >= var.settings.outage","groups":[],"manualExpression":true,"section":"2. Разметка и подсчёт обращений","rule":{"all":[{"left":"=var.outage.serviceId","operator":"notNull"},{"left":"=var.outage.probability","operator":">=","right":"=var.settings.outage"}]}}},{"id":"inc-ignore","type":"OPERATION","label":"Не считать","x":1760,"y":570,"config":{"section":"2. Разметка и подсчёт обращений","arguments":{"signalId":"=var.outage.signalId","decision":"IGNORED","incidentId":null},"resultVariable":"","operation":"signal.mark"}},{"id":"inc-count","type":"OPERATION","label":"Посчитать обращения в окне","x":1760,"y":820,"co